#include <reg51.h>
sbit K = P3^4;
unsigned char code tab[] = {0xC0,0xF9,0xA4,0xB0,0x99,
                            0x92,0x82,0xF8,0x80,0x90};
void delay(unsigned int x){ while(x--); }
void main()
{
    unsigned char n = 0;
    P1 = tab[n];
    while(1)
    {
        if(K == 0)
        {
            delay(1000);
            if(K == 0)
            {
                n++;
                if(n > 9) n = 0;
                P1 = tab[n];
                while(K == 0);
            }
        }
    }
}

